package fixture

import "testing"

func TestReverse(t *testing.T) {
	if got := Reverse("abc"); got != "cba" {
		t.Fatalf("Reverse(abc) = %q, want cba", got)
	}
	if got := Reverse(""); got != "" {
		t.Fatalf("Reverse(empty) = %q", got)
	}
}
